$(
-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-
  Definition and basic properties
-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-
$)

  $c SimpGrp $.

  $( Extend class notation with the class of simple groups. $)
  csimpg $a class SimpGrp $.

  $( Define class of all simple groups.  A simple group is a group ( ~ df-grp )
     with exactly two normal subgroups.  These are always the subgroup of all
     elements and the subgroup containing only the identity ( ~ simpgnsgbid ).
     (Contributed by Rohan Ridenour, 3-Aug-2023.) $)
  df-simpg $a |- SimpGrp = { g e. Grp | ( NrmSGrp ` g ) ~~ 2o } $.

  ${
    $d g G $.
    $( The predicate "is a simple group".  (Contributed by Rohan Ridenour,
       3-Aug-2023.) $)
    issimpg $p |- ( G e. SimpGrp <-> ( G e. Grp /\ ( NrmSGrp ` G ) ~~ 2o ) ) $=
      ( vg cnsg cfv c2o cen wbr cgrp csimpg wceq fveq2 breq1d df-simpg elrab2
      cv ) BOZCDZEFGACDZEFGBAHIPAJQREFPACKLBMN $.
  $}

  ${
    issimpgd.1 $e |- ( ph -> G e. Grp ) $.
    issimpgd.2 $e |- ( ph -> ( NrmSGrp ` G ) ~~ 2o ) $.
    $( Deduce a simple group from its properties.  (Contributed by Rohan
       Ridenour, 3-Aug-2023.) $)
    issimpgd $p |- ( ph -> G e. SimpGrp ) $=
      ( cgrp wcel cnsg cfv c2o cen wbr csimpg issimpg sylanbrc ) ABEFBGHIJKBLFC
      DBMN $.
  $}

  $( A simple group is a group.  (Contributed by Rohan Ridenour,
     3-Aug-2023.) $)
  simpggrp $p |- ( G e. SimpGrp -> G e. Grp ) $=
    ( csimpg wcel cgrp cnsg cfv c2o cen wbr issimpg simplbi ) ABCADCAEFGHIAJK
    $.

  ${
    simpggrpd.1 $e |- ( ph -> G e. SimpGrp ) $.
    $( A simple group is a group.  (Contributed by Rohan Ridenour,
       3-Aug-2023.) $)
    simpggrpd $p |- ( ph -> G e. Grp ) $=
      ( csimpg wcel cgrp simpggrp syl ) ABDEBFECBGH $.
  $}

  $( A simple group has two normal subgroups.  (Contributed by Rohan Ridenour,
     3-Aug-2023.) $)
  simpg2nsg $p |- ( G e. SimpGrp -> ( NrmSGrp ` G ) ~~ 2o ) $=
    ( csimpg wcel cgrp cnsg cfv c2o cen wbr issimpg simprbi ) ABCADCAEFGHIAJK
    $.

  ${
    trivnsimpgd.1 $e |- B = ( Base ` G ) $.
    trivnsimpgd.2 $e |- .0. = ( 0g ` G ) $.
    trivnsimpgd.3 $e |- ( ph -> G e. Grp ) $.
    trivnsimpgd.4 $e |- ( ph -> B = { .0. } ) $.
    $( Trivial groups are not simple.  (Contributed by Rohan Ridenour,
       3-Aug-2023.) $)
    trivnsimpgd $p |- ( ph -> -. G e. SimpGrp ) $=
      ( cnsg cfv c2o cen wbr csimpg wcel csn snnen2o trivnsgd breq1d mtbiri
      simpg2nsg nsyl ) ACIJZKLMZCNOAUDBPZKLMBQAUCUEKLABCDEFGHRSTCUAUB $.
  $}

  ${
    simpgntrivd.1 $e |- B = ( Base ` G ) $.
    simpgntrivd.2 $e |- .0. = ( 0g ` G ) $.
    simpgntrivd.3 $e |- ( ph -> G e. SimpGrp ) $.
    $( Simple groups are nontrivial.  (Contributed by Rohan Ridenour,
       3-Aug-2023.) $)
    simpgntrivd $p |- ( ph -> -. B = { .0. } ) $=
      ( csn wceq csimpg wcel adantr cgrp simpggrpd simpr trivnsimpgd pm2.65da
      wa ) ABDHIZCJKZATSGLASRBCDEFACMKSACGNLASOPQ $.
  $}

  ${
    $d x .0. $.  $d x B $.
    simpgnideld.1 $e |- B = ( Base ` G ) $.
    simpgnideld.2 $e |- .0. = ( 0g ` G ) $.
    simpgnideld.3 $e |- ( ph -> G e. SimpGrp ) $.
    $( A simple group contains a nonidentity element.  (Contributed by Rohan
       Ridenour, 3-Aug-2023.) $)
    simpgnideld $p |- ( ph -> E. x e. B -. x = .0. ) $=
      ( cv wceq wral wn wrex csn simpgntrivd c0 wne wb cgrp wcel cmnd simpggrpd
      grpmnd mndidcl 3syl ne0d eqsn syl mtbid rexnal sylibr ) ABIEJZBCKZLULLBCM
      ACENJZUMACDEFGHOACPQUNUMRACEADSTDUATECTADHUBDUCCDEFGUDUEUFBCEUGUHUIULBCUJ
      UK $.
  $}

  ${
    simpgnsgd.1 $e |- B = ( Base ` G ) $.
    simpgnsgd.2 $e |- .0. = ( 0g ` G ) $.
    simpgnsgd.3 $e |- ( ph -> G e. SimpGrp ) $.
    $( The only normal subgroups of a simple group are the group itself and the
       trivial group.  (Contributed by Rohan Ridenour, 3-Aug-2023.) $)
    simpgnsgd $p |- ( ph -> ( NrmSGrp ` G ) = { { .0. } , B } ) $=
      ( cnsg cfv csn c2o cfn wcel cen wbr a1i syl syl2anc cvv cbs cpr 2onn nnfi
      com simpg2nsg enfii simpggrpd 0idnsgd snex wceq fvex eqeltrdi simpgntrivd
      csimpg neqcomd enpr2d ensymd entr phpeqd ) ACHIZDJZBUAZAKLMZUTKNOZUTLMAKU
      DMZVCVEAUBPKUCQACUNMVDGCUEQZUTKUFRABCDEFACGUGUHAVDKVBNOUTVBNOVFAVBKAVABSS
      VASMADUIPABCTIZSBVGUJAEPCTUKULABVAABCDEFGUMUOUPUQUTKVBURRUS $.
  $}

  ${
    simpgnsgeqd.1 $e |- B = ( Base ` G ) $.
    simpgnsgeqd.2 $e |- .0. = ( 0g ` G ) $.
    simpgnsgeqd.3 $e |- ( ph -> G e. SimpGrp ) $.
    simpgnsgeqd.4 $e |- ( ph -> A e. ( NrmSGrp ` G ) ) $.
    $( A normal subgroup of a simple group is either the whole group or the
       trivial subgroup.  (Contributed by Rohan Ridenour, 3-Aug-2023.) $)
    simpgnsgeqd $p |- ( ph -> ( A = { .0. } \/ A = B ) ) $=
      ( csn cpr wcel wceq wo cnsg cfv simpgnsgd eleqtrd elpri syl ) ABEJZCKZLBU
      AMBCMNABDOPUBIACDEFGHQRBUACST $.
  $}

  ${
    $d ph x $.  $d x .0. $.  $d x B $.  $d x G $.
    2nsgsimpgd.1 $e |- B = ( Base ` G ) $.
    2nsgsimpgd.2 $e |- .0. = ( 0g ` G ) $.
    2nsgsimpgd.3 $e |- ( ph -> G e. Grp ) $.
    2nsgsimpgd.4 $e |- ( ph -> -. { .0. } = B ) $.
    2nsgsimpgd.5 $e |- ( ( ph /\ x e. ( NrmSGrp ` G ) ) ->
      ( x = { .0. } \/ x = B ) ) $.
    $( If any normal subgroup of a nontrivial group is either the trivial
       subgroup or the whole group, the group is simple.  (Contributed by Rohan
       Ridenour, 3-Aug-2023.) $)
    2nsgsimpgd $p |- ( ph -> G e. SimpGrp ) $=
      ( wcel wa wceq adantl simpr syl adantr eqeltrd adantlr cvv cfv csn cpr cv
      cnsg c2o cen wo elprg mpbird cgrp 0nsg nsgid elpri mpjaodan impbida eqrdv
      wb snex a1i cbs fvexi enpr2d eqbrtrd issimpgd ) ADHADUEUAZEUBZCUCZUFUGABV
      FVHABUDZVFKZVIVHKZAVJLVKVIVGMZVICMZUHZJVJVKVNURAVIVGCVFUINUJAVKLVLVJVMAVL
      VJVKAVLLVIVGVFAVLOAVGVFKZVLADUKKZVOHDEGULPQRSAVMVJVKAVMLVICVFAVMOACVFKZVM
      AVPVQHCDFUMPQRSVKVNAVIVGCUNNUOUPUQAVGCTTVGTKAEUSUTCTKACDVAFVBUTIVCVDVE $.
  $}

  ${
    $d ph x $.  $d x .0. $.  $d x B $.  $d x G $.
    simpgnsgbid.1 $e |- B = ( Base ` G ) $.
    simpgnsgbid.2 $e |- .0. = ( 0g ` G ) $.
    simpgnsgbid.3 $e |- ( ph -> G e. Grp ) $.
    simpgnsgbid.4 $e |- ( ph -> -. { .0. } = B ) $.
    $( A nontrivial group is simple if and only if its normal subgroups are
       exactly the group itself and the trivial subgroup.  (Contributed by
       Rohan Ridenour, 4-Aug-2023.) $)
    simpgnsgbid $p |- ( ph ->
    ( G e. SimpGrp <-> ( NrmSGrp ` G ) = { { .0. } , B } ) ) $=
      ( vx csimpg wcel cnsg cfv csn cpr wceq wa simpr simpgnsgd adantr wn cv wo
      cgrp simplr eleqtrd elpri syl 2nsgsimpgd impbida ) ACJKZCLMZDNZBOZPZAUKQB
      CDEFAUKRSAUOQZIBCDEFACUDKUOGTAUMBPUAUOHTUPIUBZULKZQZUQUNKUQUMPUQBPUCUSUQU
      LUNUPURRAUOURUEUFUQUMBUGUHUIUJ $.
  $}


$(
-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-
  Classification of abelian simple groups
-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-.-
$)

  ${
    ablsimpnosubgd.1 $e |- B = ( Base ` G ) $.
    ablsimpnosubgd.2 $e |- .0. = ( 0g ` G ) $.
    ablsimpnosubgd.3 $e |- ( ph -> G e. Abel ) $.
    ablsimpnosubgd.4 $e |- ( ph -> G e. SimpGrp ) $.
    ablsimpnosubgd.5 $e |- ( ph -> S e. ( SubGrp ` G ) ) $.
    ablsimpnosubgd.6 $e |- ( ph -> A e. S ) $.
    ablsimpnosubgd.7 $e |- ( ph -> -. A = .0. ) $.
    $( A subgroup of an abelian simple group containing a nonidentity element
       is the whole group.  (Contributed by Rohan Ridenour, 3-Aug-2023.) $)
    ablsimpnosubgd $p |- ( ph -> S = B ) $=
      ( csn wceq wcel elsni nsyl eleq2 cfv syl5ibcom mtod pm2.21d idd cnsg cabl
      csubg ablnsg eqcomd syl eleqtrd simpgnsgeqd mpjaod ) ADFNZOZDCOZUPAUOUPAU
      OBUNPZABFOUQMBFQRABDPUOUQLDUNBSUAUBUCAUPUDADCEFGHJADEUGTZEUETZKAEUFPZURUS
      OIUTUSUREUHUIUJUKULUM $.
  $}

  ${
    $d ph n $.  $d .x. n $.  $d A n $.  $d C n $.  $d B n $.  $d G n $.
    ablsimpg1gend.1 $e |- B = ( Base ` G ) $.
    ablsimpg1gend.2 $e |- .0. = ( 0g ` G ) $.
    ablsimpg1gend.3 $e |- .x. = ( .g ` G ) $.
    ablsimpg1gend.4 $e |- ( ph -> G e. Abel ) $.
    ablsimpg1gend.5 $e |- ( ph -> G e. SimpGrp ) $.
    ablsimpg1gend.6 $e |- ( ph -> A e. B ) $.
    ablsimpg1gend.7 $e |- ( ph -> -. A = .0. ) $.
    ablsimpg1gend.8 $e |- ( ph -> C e. B ) $.
    $( An abelian simple group is generated by any non-identity element.
       (Contributed by Rohan Ridenour, 3-Aug-2023.) $)
    ablsimpg1gend $p |- ( ph -> E. n e. ZZ C = ( n .x. A ) ) $=
      ( cz cv co cmpt simpggrpd cycsubgcld cycsubggend ablsimpnosubgd elrnmpt2d
      eqid crn eleqtrrd ) AFQFRBESZDFQUITZUJUFZADCUJUGZPABCULGHIJLMABCEFUJGIKUK
      AGMUANUBABCEFUJGIKUKNUCOUDUHUE $.
  $}

  ${
    $d ph x y z $.  $d x y z G $.
    ablsimpgcygd.1 $e |- ( ph -> G e. Abel ) $.
    ablsimpgcygd.2 $e |- ( ph -> G e. SimpGrp ) $.
    $( An abelian simple group is cyclic.  (Contributed by Rohan Ridenour,
       3-Aug-2023.)  (Proof shortened by Rohan Ridenour, 31-Oct-2023.) $)
    ablsimpgcygd $p |- ( ph -> G e. CycGrp ) $=
      ( vx vy vz cv c0g cfv wceq wn ccyg wcel cbs eqid simpgnideld cmg ad2antrr
