    $( Ring plus $)
    issrngd.p $e |- ( ph -> .+ = ( +g ` R ) ) $.
    $( Ring times $)
    issrngd.t $e |- ( ph -> .x. = ( .r ` R ) ) $.
    $( Involution (e.g., complex conjugate) $)
    issrngd.c $e |- ( ph -> .* = ( *r ` R ) ) $.
    issrngd.r $e |- ( ph -> R e. Ring ) $.
    $( Closure $)
