$(
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
  Definition and basic properties
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
$)

  $c LVec $.

  $( Extend class notation with class of all left vector spaces. $)
  clvec $a class LVec $.

  $( Define the class of all left vector spaces.  A left vector space over a
     division ring is an Abelian group (vectors) together with a division ring
     (scalars) and a left scalar product connecting them.  Some authors call
     this a "left module over a division ring", reserving "vector space" for
     those where the division ring is commutative, i.e., is a field.
     (Contributed by NM, 11-Nov-2013.) $)
  df-lvec $a |- LVec = { f e. LMod | ( Scalar ` f ) e. DivRing } $.

  ${
    $d f F $.  $d f W $.
    islvec.1 $e |- F = ( Scalar ` W ) $.
    $( The predicate "is a left vector space".  (Contributed by NM,
       11-Nov-2013.) $)
    islvec $p |- ( W e. LVec <-> ( W e. LMod /\ F e. DivRing ) ) $=
      ( vf cv csca cfv cdr wcel clmod clvec fveq2 eqtr4di eleq1d df-lvec elrab2
      wceq ) DEZFGZHIAHIDBJKRBQZSAHTSBFGARBFLCMNDOP $.

    $( The set of scalars of a left vector space is a division ring.
       (Contributed by NM, 17-Apr-2014.) $)
    lvecdrng $p |- ( W e. LVec -> F e. DivRing ) $=
      ( clvec wcel clmod cdr islvec simprbi ) BDEBFEAGEABCHI $.
  $}

  $( A left vector space is a left module.  (Contributed by NM, 9-Dec-2013.) $)
  lveclmod $p |- ( W e. LVec -> W e. LMod ) $=
    ( clvec wcel clmod csca cfv cdr eqid islvec simplbi ) ABCADCAEFZGCKAKHIJ $.

  ${
    lveclmodd.1 $e |- ( ph -> W e. LVec ) $.
    $( A vector space is a left module.  (Contributed by SN, 16-May-2024.) $)
    lveclmodd $p |- ( ph -> W e. LMod ) $=
      ( clvec wcel clmod lveclmod syl ) ABDEBFECBGH $.
  $}

  ${
    lvecgrpd.1 $e |- ( ph -> W e. LVec ) $.
    $( A vector space is a group.  (Contributed by SN, 16-May-2024.) $)
    lvecgrpd $p |- ( ph -> W e. Grp ) $=
      ( lveclmodd lmodgrpd ) ABABCDE $.
  $}

  ${
    lsslvec.x $e |- X = ( W |`s U ) $.
    lsslvec.s $e |- S = ( LSubSp ` W ) $.
    $( A vector subspace is a vector space.  (Contributed by NM,
       14-Mar-2015.) $)
    lsslvec $p |- ( ( W e. LVec /\ U e. S ) -> X e. LVec ) $=
      ( clvec wcel wa clmod csca cfv lveclmod lsslmod sylan wceq resssca adantl
      cdr eqid lvecdrng adantr eqeltrrd islvec sylanbrc ) CGHZBAHZIZDJHZDKLZSHD
