    ${
      ip0l.z $e |- Z = ( 0g ` F ) $.
      $( Orthogonality (meaning inner product is 0) is commutative.
         (Contributed by NM, 17-Apr-2008.)  (Revised by Mario Carneiro,
         7-Oct-2015.) $)
      iporthcom $p |- ( ( W e. PreHil /\ A e. V /\ B e. V ) ->
        ( ( A ., B ) = Z <-> ( B ., A ) = Z ) ) $=
        ( wcel co cfv wceq 3ad2ant1 eqid syl stafval eqtrd cphl w3a cstf cbs wb
        wf1 wf1o phlsrng srngf1o f1of1 3syl ipcl clmod phllmod lmod0cl syl12anc
