    isphld.f $e |- ( ph -> F = ( Scalar ` W ) ) $.
    $( Division ring (skew field) base $)
    isphld.k $e |- ( ph -> K = ( Base ` F ) ) $.
    $( Division ring (skew field) plus $)
    isphld.p $e |- ( ph -> .+^ = ( +g ` F ) ) $.
    $( Division ring (skew field) times $)
    isphld.t $e |- ( ph -> .X. = ( .r ` F ) ) $.
    $( Involution (e.g., complex conjugate) $)
    isphld.c $e |- ( ph -> .* = ( *r ` F ) ) $.
    $( Division ring zero $)
    isphld.o $e |- ( ph -> O = ( 0g ` F ) ) $.
    isphld.l $e |- ( ph -> W e. LVec ) $.
    isphld.r $e |- ( ph -> F e. *Ring ) $.
    $( Closure of inner product $)
    isphld.cl $e |- ( ( ph /\ x e. V /\ y e. V ) -> ( x I y ) e. K ) $.
    $( Distributive law for inner product $)
    isphld.d $e |- ( ( ph /\ q e. K /\ ( x e. V /\ y e. V /\ z e. V ) ) ->
      ( ( ( q .x. x ) .+ y ) I z ) = ( ( q .X. ( x I z ) ) .+^ ( y I z ) ) ) $.
